    xz = ((*qua)[0] * (*qua)[2] + 0x400) >> 11;
    yy = ((*qua)[1] * (*qua)[1] + 0x400) >> 11;
    xw = ((*qua)[0] * (*qua)[3] + 0x400) >> 11;
    yw = ((*qua)[1] * (*qua)[3] + 0x400) >> 11;
    zz = ((*qua)[2] * (*qua)[2] + 0x400) >> 11;
    zw = ((*qua)[2] * (*qua)[3] + 0x400) >> 11;
    yz = ((*qua)[1] * (*qua)[2] + 0x400) >> 11;
    m->m[0][0] = 4096 - (yy + zz);
