    m->m[0][2] = xz + yw;
    m->m[1][0] = xy + zw;
    m->m[1][1] = 4096 - (xx + zz);
    m->m[1][2] = yz - xw;
    m->m[2][1] = yz + xw;
    m->m[2][0] = xz - yw;
    m->m[2][2] = 4096 - (xx + yy);
