/* ---------------- jump_debris (src/pilot/jump_debris.c) ---------------- */
static inline int jit(void) { int r = func_000776E4() & 0x1ff; return r - 256; }
/* Driver 2: jump_debris */
void jump_debris(CAR_DATA *cp)
{
    int count;
    VECTOR position, velocity;

    for (count = 0; count < 4; count++) {
        if (cp->wheel[count].susCompression != 0) {
            D_0009678C = 0;
            D_00097010 = 1;
            return;
        }
    }
    if (D_00097010) {
        D_0009678C = 80;
        D_00097010 = 0;
        if (*(int *)&D_00096834 != 6)
            func_00020998(cp);
    }
    if (D_0009678C != 0 && --D_0009678C < 75) {
        memset(&velocity, 0, 16);
        velocity.vx = cp->pos.vx + jit();
        velocity.vy = 200 - cp->pos.vy;
        velocity.vz = cp->pos.vz + jit();
        position = velocity;
        memset(&velocity, 0, 16);
        Setup_Debris(&position, &velocity, 5, 0xb);
    }
}

